/**
 * Per-room animated water layout (ch2): river + waterfall.
 *
 * Water is **decoration**, not collision: player/enemy still walk through (shallow river).
 * So this data lives outside `LevelData.obstacles`, used only to place ripple/waterfall
 * sprites. Source file: `assets/resources/data/water-layout.json`, generated by
 * `scripts/dress-rooms.ts` together with the decor layer.
 *
 * Pure TS: tests read the real JSON, check coordinates are inside the room and do not cover spawn points.
 */
import { ROOM_COLS, ROOM_ROWS } from './level-data';

export const WATER_KINDS = ['river', 'waterfall'] as const;
export type WaterKind = (typeof WATER_KINDS)[number];

/**
 * Largest room a water area may address: a normal room is 4×4 screens (ADR-018, #37/#38). Water is
 * decoration only, so the bound just has to keep a typo from pointing outside every possible room.
 */
export const MAX_ROOM_COLS = ROOM_COLS * 4;
export const MAX_ROOM_ROWS = ROOM_ROWS * 4;

export interface WaterArea {
  readonly kind: WaterKind;
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

export interface WaterLayout {
  readonly version: 1;
  /** `rooms[chapter][room]` */
  readonly rooms: Readonly<Record<string, Readonly<Record<string, readonly WaterArea[]>>>>;
}

const VERSION = 1;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isArea(value: unknown): value is WaterArea {
  if (!isRecord(value)) return false;
  const kind = value['kind'];
  return (
    (kind === 'river' || kind === 'waterfall') &&
    typeof value['x'] === 'number' &&
    typeof value['y'] === 'number' &&
    typeof value['width'] === 'number' &&
    typeof value['height'] === 'number' &&
    Number.isFinite(value['x']) &&
    Number.isFinite(value['y']) &&
    Number.isInteger(value['x']) &&
    Number.isInteger(value['y']) &&
    Number.isInteger(value['width']) &&
    Number.isInteger(value['height']) &&
    value['width'] > 0 &&
    value['height'] > 0 &&
    value['x'] >= 0 &&
    value['y'] >= 0 &&
    value['x'] + value['width'] <= MAX_ROOM_COLS &&
    value['y'] + value['height'] <= MAX_ROOM_ROWS
  );
}

/** Validate raw JSON; throws naming the exact broken chapter/room/area. */
export function parseWaterLayout(raw: unknown): WaterLayout {
  if (!isRecord(raw)) throw new Error('water-layout must be an object');
  if (raw['version'] !== VERSION) {
    throw new Error(`water-layout.version must be ${VERSION}, got ${String(raw['version'])}`);
  }
  if (!isRecord(raw['rooms'])) throw new Error('water-layout.rooms must be an object');

  const rooms: Record<string, Record<string, readonly WaterArea[]>> = {};
  for (const [chapter, byRoom] of Object.entries(raw['rooms'])) {
    if (!isRecord(byRoom)) throw new Error(`water-layout.rooms["${chapter}"] must be an object`);
    const parsedRooms: Record<string, readonly WaterArea[]> = {};
    for (const [room, areas] of Object.entries(byRoom)) {
      if (!Array.isArray(areas)) {
        throw new Error(`water-layout chapter ${chapter} room ${room} must be an array`);
      }
      const parsed: WaterArea[] = [];
      for (const [index, area] of areas.entries()) {
        if (!isArea(area)) {
          throw new Error(
            `water-layout chapter ${chapter} room ${room} area[${index}] is invalid ` +
              `(kind river|waterfall, integers, inside ${MAX_ROOM_COLS}×${MAX_ROOM_ROWS})`,
          );
        }
        parsed.push({ kind: area.kind, x: area.x, y: area.y, width: area.width, height: area.height });
      }
      parsedRooms[room] = parsed;
    }
    rooms[chapter] = parsedRooms;
  }

  return { version: VERSION, rooms };
}

/** Area array of one room; `[]` when the room has no water. */
export function waterAreasFor(
  layout: WaterLayout,
  chapter: number,
  room: number,
): readonly WaterArea[] {
  return layout.rooms[String(chapter)]?.[String(room)] ?? [];
}

/** Whether a (tile) cell falls inside an area — for tests/debug tools. */
export function areaContains(area: WaterArea, x: number, y: number): boolean {
  return x >= area.x && x < area.x + area.width && y >= area.y && y < area.y + area.height;
}
